package com.google.javascript.rhino;

import com.google.javascript.rhino.JSDocInfo.Visibility;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.reflect.Whitebox;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for JSDocInfoBuilder#addAuthor.
 */
public class JSDocInfoBuilder_addAuthor_TriageGen0Test {

    private JSDocInfoBuilder builder;
    private com.google.javascript.rhino.JSDocInfo currentInfoMock;

    @Before
    public void setUp() {
        // Initialize the builder
        builder = new JSDocInfoBuilder(true);

        // Since currentInfo is a private field, we use reflection (Whitebox) 
        // to inject a mock to control the behavior of documentAuthor(author)
        currentInfoMock = mock(com.google.javascript.rhino.JSDocInfo.class);
        Whitebox.setField(builder, "currentInfo", currentInfoMock);
    }

    @Test
    public void testAddAuthor_ReturnsTrueWhenAuthorExists() {
        String authorName = "John Doe";

        // Setup: documentAuthor returns true
        when(currentInfoMock.documentAuthor(authorName)).thenReturn(true);

        // Execute
        boolean result = builder.addAuthor(authorName);

        // Verify
        assertTrue("addAuthor should return true when author is present", result);
        assertTrue("populated should be set to true", builder.isPopulated());
    }

    @Test
    public void testAddAuthor_ReturnsFalseWhenAuthorDoesNotExist() {
        String authorName = "Unknown Author";

        // Setup: documentAuthor returns false
        when(currentInfoMock.documentAuthor(authorName)).thenReturn(false);

        // Execute
        boolean result = builder.addAuthor(authorName);

        // Verify
        assertFalse("addAuthor should return false when author is not present", result);
        // Note: Based on the code, if it returns false, 'populated' is not updated to true
        // We assume it was false initially or remains unchanged.
    }

    @Test
    public void testAddAuthor_WithNullAuthor() {
        // Testing edge case for null input
        when(currentInfoMock.documentAuthor(null)).thenReturn(false);

        boolean result = builder.addAuthor(null);

        assertFalse(result);
    }

    @Test
    public void testAddAuthor_EmptyStringAuthor() {
        // Testing edge case for empty string
        when(currentInfoMock.documentAuthor("")).thenReturn(true);

        boolean result = builder.addAuthor("");

        assertTrue(result);
        assertTrue(builder.isPopulated());
    }
}
